/**
 * Hygiene helper for tsx's global disk transform cache (`$TMPDIR/tsx-<uid>`).
 *
 * Why: temporary-dir `.mts/.tsx` scripts generated by restart/plugin tests use unique paths that
 * never cache-hit across runs, bloating `/tmp/tsx-<uid>` with hundreds of thousands of entries.
 * In `tsx@4.23.15`, every cache miss triggers `expireDiskCache()` which scans the entire directory
 * via `fs.promises.opendir` and stalls test process exit by 4–25s.
 *
 * Strictly unlinks hash cache entries matching `TSX_CACHE_FILE_RE` (`/^\d+-[0-9a-f]+$/`),
 * never touching `.pipe` sockets or unrelated files.
 */
import { readdirSync, unlinkSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

export const TSX_CACHE_FILE_RE = /^\d+-[0-9a-f]+$/;
export const DEFAULT_MAX_TSX_CACHE_ENTRIES = 3000;

export function resolveTsxCacheDir(tmpDir = os.tmpdir()) {
  const id = typeof process.geteuid === 'function' ? process.geteuid() : os.userInfo().username;
  return path.join(tmpDir, `tsx-${id}`);
}

/**
 * Inspect `cacheDir` and delete all cached transform entries if count exceeds `maxEntries`.
 * Never throws on missing/unreadable directories or transient EPERM/ENOENT unlink races.
 */
export function pruneTsxCacheIfBloated({
  cacheDir = resolveTsxCacheDir(),
  maxEntries = DEFAULT_MAX_TSX_CACHE_ENTRIES,
} = {}) {
  let names;
  try {
    names = readdirSync(cacheDir);
  } catch {
    return { cacheDir, total: 0, pruned: 0 };
  }

  const matching = names.filter((name) => TSX_CACHE_FILE_RE.test(name));
  if (matching.length <= maxEntries) {
    return { cacheDir, total: matching.length, pruned: 0 };
  }

  let pruned = 0;
  for (const name of matching) {
    try {
      unlinkSync(path.join(cacheDir, name));
      pruned += 1;
    } catch {
      // Ignore ENOENT / EPERM from concurrent test workers
    }
  }
  return { cacheDir, total: matching.length, pruned };
}
